#include <vector>
#include <limits>
#include <cstddef>
#include <omp.h>

int smallestOdd(std::vector<int> const& x) {
    int minOdd = std::numeric_limits<int>::max();
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for reduction(min:minOdd)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const int v = x[static_cast<std::size_t>(i)];
        if ((v % 2) != 0 && v < minOdd) {
            minOdd = v;
        }
    }

    return minOdd; // If no odd value exists, returns std::numeric_limits<int>::max().
}
